Q[6] = { id = 6, title = "Bounty on Garrick Padfoot", lvl = 5, min = 2, prev = 18, text = "Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain's head, and earn his bounty!$B$BBut be wary, $N.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.", goal = "Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.", done = "Hah - you caught him! You've done Elwynn a great service, and earned a nice bounty!", ask = "Did you find Garrick's shack? Are we finally free of that villain?", giver = 823, ender = 823, items = { { id = 182, count = 1, name = "Garrick's Head", from = { { 103, 100 } } } } }
Q[7] = { id = 7, title = "Kobold Camp Cleanup", lvl = 2, min = 1, prev = 783, text = "Your first task is one of cleansing, $N.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.", goal = "Kill 10 Kobold Vermin, then return to Marshal McBride.", done = "Well done, citizen. Those kobolds are thieves and cowards, but in large numbers they pose a threat to us. And the humans of Stormwind do not need another threat.$B$BFor defeating them, you have my gratitude.", ask = "How goes the hunting, $N? Have you found and defeated those vermin?", money = 25, giver = 197, ender = 197, kill = { { entry = 6, count = 10, name = "Kobold Vermin" } } }
Q[15] = { id = 15, title = "Investigate Echo Ridge", lvl = 3, min = 1, prev = 7, text = "$N, my scouts tell me that the kobold infestation is larger than we had thought.  A group of kobold workers has camped near the Echo Ridge Mine to the north.$B$BGo to the mine and remove them.  We know there are at least 10.  Kill them, see if there are more, then report back to me.", goal = "Kill 10 Kobold Workers, then report back to Marshal McBride.", done = "I don't like hearing of all these kobolds in our mine. No good can come of this. Here, take this as payment, and when you're ready, speak to me again. I would like you to go back to the mines one more time...", ask = "Have you been to the mines? Are you ready to report?", money = 40, giver = 197, ender = 197, kill = { { entry = 257, count = 10, name = "Kobold Worker" } } }
Q[18] = { id = 18, title = "Brotherhood of Thieves", lvl = 4, min = 2, prev = 783, text = "Recently, a new group of thieves has been hanging around Northshire.  They call themselves the Defias Brotherhood, and have been seen across the river to the east.$B$BI don't know what they're up to, but I'm sure it's not good!  Bring me the bandanas they wear, and I'll reward you with a weapon.", goal = "Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.", done = "Back with some bandanas, I see. The Stormwind Army appreciates your help.", ask = "Have you gathered those bandanas for me yet?", giver = 823, ender = 823, items = { { id = 752, count = 12, name = "Red Burlap Bandana", from = { { 38, 80 } } } } }
Q[21] = { id = 21, title = "Skirmish at Echo Ridge", lvl = 5, min = 1, prev = 15, text = "Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.$B$BWaste no time, $N.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.", goal = "Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.", done = "Once again, you have earned my respect, and the gratitude of the Stormwind Army. There may yet be kobolds in the mine, but I will marshal others against them. We have further tasks for you.", ask = "I know it's bloody work, $N, but it's vital to the safety of Northshire. Are you ready to report?", giver = 197, ender = 197, kill = { { entry = 80, count = 12, name = "Kobold Laborer" } } }
Q[33] = { id = 33, title = "Wolves Across the Border", lvl = 2, min = 1, prev = 5261, text = "I hate those nasty timber wolves!  But I sure like eating wolf steaks...  Bring me tough wolf meat and I will exchange it for something you'll find useful.$B$BTough wolf meat is gathered from hunting the timber wolves and young wolves wandering the Northshire countryside.", goal = "Bring 8 pieces of Tough Wolf Meat to Eagan Peltskinner outside Northshire Abbey.", done = "You've been busy! I can't wait to cook up that wolf meat...$B$BI have some things here you want - take your pick!", ask = "Hey $N. I'm getting hungry...did you get that tough wolf meat?", giver = 196, ender = 196, items = { { id = 750, count = 8, name = "Tough Wolf Meat", from = { { 705, 80 }, { 704, 80 }, { 299, 80 }, { 69, 80 } } } } }
Q[54] = { id = 54, title = "Report to Goldshire", lvl = 5, min = 1, prev = 21, text = "$N, you are a $c with proven interest in the security of Northshire.  You are now tasked with the protection of the surrounding Elwynn Forest.$B$BIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire.  Goldshire lies along the southern road, past the border gates.", goal = "Take Marshal McBride's Documents to Marshal Dughan in Goldshire.", done = "Well, it says here that you've been awarded Acting Deputy Status with the Stormwind Marshals. Congratulations.$b$bAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!$b$bIt's hard to keep track of politics in these dark days...", ask = "You have word from McBride? Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report.$b$bHere, let me have his papers...", giver = 197, ender = 240, enderName = "Marshal Dughan", items = { { id = 745, count = 1, name = "Marshal McBride's Documents", from = {  } } }, rewards = { "Pikeman Shield" } }
Q[344] = { id = 344, title = "Brother Paxton", lvl = 24, min = 20, prev = 343, text = "The Stresses of Iron?  Yes, I know the book.  Quite a good one, written by the Dwarven miner Margulf Blaggon a few decades ago.  He spent most his time deep in the mountains of Khaz Modan, digging ore.  Smart fellow!$B$BBut where was I?  Oh yes, the Stresses of Iron!  I'm afraid the book was moved to the Northshire Abbey.  The caretaker of the Abbey's library, Brother Paxton, wanted to make a copy of the book for his own shelves.$B$BBut that was months ago.  I wonder why it's taking him so long...", goal = "Speak with Brother Paxton in the Northshire Abbey.", done = "Mr. Sheaf is wondering where his book is? Well this is a tad embarrassing. I have the book, but I'm still making my copy and I'm not quite ready to give the original up!", ender = 951 }
Q[345] = { id = 345, title = "Ink Supplies", lvl = 24, min = 20, prev = 344, text = "I've been meaning to finish my copy of The Stresses of Iron, but...$B$BWell you see, I make my own ink for books I copy.  It's my own recipe; it doesn't run or smear, and it dries very quickly  Unfortunately, it dries too quickly!  My last batch dried up before I could finish the copying job, and I haven't had the chance to make more ink!$B$BTo make more I need Rethban Iron Ore from the Redridge Mountains.  Foreman Oslow in Lakeshire is my usual supplier.", goal = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.", done = "You need what?? Maybe you haven't noticed, but we're busy fortifying Lakeshire's defenses and repairing damage from recent orc attacks. If you need Rethban Iron Ore, you'll have to get it yourself!", giver = 951, ender = 341, enderName = "Foreman Oslow" }
Q[346] = { id = 346, title = "Return to Kristoff", lvl = 24, min = 20, prev = 347, text = "Now that I've finished copying the book, here's the original Stresses of Iron.  Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay.", goal = "Return to Brother Kristoff in the Cathedral Square.  Give him the book The Stresses of Iron.", done = "That's the one! Thank you, $N. May the Light shine brightly upon both your body and spirit!", ask = "Were you able to find the book?", giver = 951, ender = 1444, enderName = "Brother Kristoff", items = { { id = 2795, count = 1, name = "Book: Stresses of Iron", from = {  } } }, rewards = { "Wandering Boots" } }
Q[347] = { id = 347, title = "Rethban Ore", lvl = 24, min = 20, prev = 345, text = "Rethban Ore is named after the man who first found it, Bart Rethban.  When smelted it's not as strong as iron, but its ore has a dark, flat color that some scribes use in their dyes.  It can be found in the Rethban Caverns, north of here.$B$BWe usually have some in stock, but we're too busy preparing for Orc attacks to gather any.  And besides...Redridge Gnolls are now living in the Rethban Caverns and their Drudgers are gathering the ore themselves.$B$BSo if you need some, you'll have to get it yourself.", goal = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.", done = "Oh, splendid! I can use this ore to make my dye, and then can finish copying The Stresses of Iron.$B$BThank you, $N!", ask = "Do you have the Rethban Ore?", ender = 951, items = { { id = 2798, count = 5, name = "Rethban Ore", from = { { 580, 33.83 }, { -2055, 33 }, { -2054, 33 } } } } }
Q[783] = { id = 783, title = "A Threat Within", lvl = 1, min = 1, text = "I hope you strapped your belt on tight, young $c, because there is work to do here in Northshire.$B$BAnd I don't mean farming.$B$BThe Stormwind guards are hard pressed to keep the peace here, with so many of us in distant lands and so many threats pressing close.  And so we're enlisting the aid of anyone willing to defend their home.  And their alliance.$B$BIf you're here to answer the call, then speak with my superior, Marshal McBride.  He's inside the abbey behind me.", goal = "Speak with Marshal McBride.", done = "Ah, good.  Another volunteer.  We're getting a lot of you these days.$B$BI hope it's enough.$B$BThe human lands are threatened from without, and so many of our forces have been marshaled abroad.  This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.$B$BIt is a many-fronted battle we wage, $N.  Gird yourself for a long campaign.", giver = 823, ender = 197 }
Q[1598] = { id = 1598, title = "The Stolen Tome", lvl = -1, min = 1, classes = 256, text = "You there! $n, right?$b$bI hope you're sure about becoming a warlock, because if you can't hold your own, you're likely to get pulled under.$b$bI'm to teach you, but I need to make sure you're strong enough first.$b$bThere was a novice studying at the Abbey who ran off to join the Defias Brotherhood. Why do I care? Well, he stole some important books.$b$bOne of those happens to be a book I've wanted for myself, the Powers of the Void. Steal it for me, they have it hidden at their tent in the Vineyards.", goal = "Retrieve the Powers of the Void for Drusilla La Salle.", done = "Excellent... I was never able to gain access to this text, it was held in a protected wing of the library that would have looked suspicious for me to be loitering around.$B$BWell, you did a good job in getting this, and I'm convinced that you can probably handle your own imp, so there's no reason for me not to show you how to summon one.", ask = "It was too conspicuous for me to steal the book myself. What luck one of their own patsies did the dirty work for me.", giver = 459, ender = 459, items = { { id = 6785, count = 1, name = "Powers of the Void", from = { { -83763, 100 } } } } }
Q[2158] = { id = 2158, title = "Rest and Relaxation", lvl = 5, min = 1, text = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!$B$BMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.$B$BTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", goal = "Speak with Innkeeper Farley at the Lion's Pride Inn.", done = "Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.$B$BWould you like to try a sampling of some of our fine food and drink?", giver = 6774, ender = 295, enderName = "Innkeeper Farley" }
Q[3100] = { id = 3100, title = "Simple Letter", lvl = 1, min = 1, prev = 7, classes = 1, text = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Llane, our local warrior trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", goal = "Read the Simple Letter and speak to Llane Beshere in Northshire Abbey.", done = "Get yourself squared away, learn the layout of the land, and come back to me whenever you need training. I'll be here night or day.$B$BThe Knights of the Silver Hand have done well in making this place fairly safe, but as you meet the other citizens, I think you'll find they all have problems they could use some help with--help a warrior can give them. Good luck.", ask = "Ah, you got my letter, $N... good.$B$BThere's been an influx of warriors in Elwynn recently - which is good for Stormwind, but bad for the kobolds and Defias in the area.", giver = 197, ender = 911, items = { { id = 9542, count = 1, name = "Simple Letter", from = {  } } } }
Q[3101] = { id = 3101, title = "Consecrated Letter", lvl = 1, min = 1, prev = 7, classes = 2, text = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Brother Sammuel, our local paladin trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", goal = "Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey.", done = "In the meantime, you should know one or two other things. You are a symbol to many here in this land--act accordingly. The Holy Light shines within you, and it will be obvious to both your allies and your enemies.$B$BAlso, as you gain in wisdom and power, you will need to train to learn new abilities. That's where I come in. When you feel you've gained some experience here in Northshire, come back to me and I will teach you what I feel you are ready to learn. Good luck... $C!", ask = "Finally! We meet face to face, brother to brother. I welcome you to Northshire. This will be your home for a short time while you learn the ins and outs of how things are done, but know that Stormwind is not far off, and sooner or later, your path will take you there. But until then, be patient... Knight of the Silver Hand.", giver = 197, ender = 925, items = { { id = 9570, count = 1, name = "Consecrated Letter", from = {  } } } }
Q[3102] = { id = 3102, title = "Encrypted Letter", lvl = 1, min = 1, prev = 7, classes = 8, text = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", goal = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.", done = "You're gonna find that there a number of outfits that'll covet our skills, $N. Adventurers, SI:7... heck, even the Defias Brotherhood wouldn't mind a spy or two inside Stormwind. But you remember this, you're your own man. Don't let nobody bully you into doing something you don't wanna do! Besides, we hold all the cards... at least, we do before the game's done. Know what I mean?$B$BAnyway, just wanted to introduce myself and let you know that I'm here if you need any training. Come by anytime.", ask = "You made it here in one piece, and it doesn't look like too many people saw you. Good enough for me. I don't like to have much attention drawn to me back here... nice and quiet. I'm sure you can understand.$b$bHave any trouble yet? I'm glad to hear not. That'll change soon enough.", giver = 197, ender = 915, items = { { id = 9555, count = 1, name = "Encrypted Letter", from = {  } } } }
Q[3103] = { id = 3103, title = "Hallowed Letter", lvl = 1, min = 1, prev = 7, classes = 16, text = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Priestess Anetta, our local priest trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", goal = "Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey.", done = "As you grow in experience, return to me and I will do what I can to impart my knowledge upon you. Until then, go with compassion in your heart, and let wisdom be your guide. Remember, the world only becomes a better place if you make it so.", ask = "Ah, at last you've come. I knew you would find your way to me. The Holy Light shines upon you, and the path you've chosen. These times are harsh--the Burning Legion still has a presence upon Azeroth, the entirety of Kalimdor seeks new ways to defend itself from its own tribulations, and it is up to you to aid as many as you can.", giver = 197, ender = 375, items = { { id = 9548, count = 1, name = "Hallowed Letter", from = {  } } } }
Q[3104] = { id = 3104, title = "Glyphic Letter", lvl = 1, min = 1, prev = 7, classes = 128, text = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Khelden, our local mage trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", goal = "Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey.", done = "Haha, I knew my note would not dissuade you from your path. So, you're prepared then, are you? Prepared to accept your fate? Prepared to challenge the gods and any other forces that stand before you in the pursuit of knowledge and power?$B$BI will not lie, $N, you will be feared as much as respected. But also know this, I will be here for you when you need training. Simply seek me out as you grow more powerful.", ask = "Hello, $N. I am Khelden. Is there something I can do for you?", giver = 197, ender = 198, items = { { id = 9571, count = 1, name = "Glyphic Letter", from = {  } } } }
Q[3105] = { id = 3105, title = "Tainted Letter", lvl = 1, min = 1, prev = 7, classes = 256, text = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Drusilla, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", goal = "Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey.", done = "As you grow in power, you will be tempted--you must always remember to control yourself. I will not lie--corruption can come to any practitioner of the arcane; especially one who deals with creatures from the Twisting Nether. Be patient, and be prudent... but do not let that repress your ambition.$B$BAs you grow more powerful, return to me and I will teach you more about our ways.", ask = "Ah, so you've arrived, and not a moment too soon, $N. Some of the guards were over here a moment ago and were giving me curious looks... pathetic mundanes.", giver = 197, ender = 459, items = { { id = 9576, count = 1, name = "Tainted Letter", from = {  } } } }
Q[3903] = { id = 3903, title = "Milly Osworth", lvl = 4, min = 2, prev = 33, text = "You've shown yourself a dependable $c, $N.  Dependable, and not afraid to get your hands dirty, eh?$B$BI have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.", goal = "Speak with Milly Osworth.", done = "Oh, Deputy Willem told you to speak with me? He's a brave man and always willing to help, but his duties keep him stuck at Northshire Abbey and I'm afraid the problem I have today is beyond him.$b$bPerhaps you can help me?", giver = 823, ender = 9296 }
Q[3904] = { id = 3904, title = "Milly's Harvest", lvl = 4, min = 2, prev = 3903, text = "A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.$B$BPlease, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.$B$BBring me those buckets!  Save my harvest!", goal = "Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.", done = "Oh thank you, $N! You saved my harvest! And I hope you showed a few of those Defias that they can't cause trouble around here.$b$bWe might be short on guards these days, but we're lucky to have heroes like you to protect us!", ask = "Do you have my harvest, $N?", giver = 9296, ender = 9296, items = { { id = 11119, count = 8, name = "Milly's Harvest", from = { { -161557, 100 } } } } }
Q[3905] = { id = 3905, title = "Grape Manifest", lvl = 4, min = 2, prev = 3904, text = "Now that my crop is saved, take this Grape Manifest to Brother Neals.  He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes.$B$BYou'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.", goal = "Bring the Grape Manifest to Brother Neals in Northshire Abbey.", done = "Let's see here...$b$bOh my! Milly's grapes have been saved! When she told me that brigands overran her vineyards I nearly despaired, but my faith in the Light did not waver!$b$bAnd through your bravery, we now have grapes for more wine! May the Light bless you, $N, and keep you safe!", ask = "You look to be in fine spirits! Come! Have a seat, and have a drink!", giver = 9296, ender = 952, items = { { id = 11125, count = 1, name = "Grape Manifest", from = {  } } } }
Q[5261] = { id = 5261, title = "Eagan Peltskinner", lvl = 2, min = 1, prev = 783, text = "Eagan Peltskinner is looking for someone to hunt wolves for him.  That's good news, because we're seeing a lot more wolves in Northshire Valley lately.$B$BIf you're interested then speak with Eagan.  He's around the side of the abbey, to the left.", goal = "Speak with Eagan Peltskinner.", done = "That's true.  I'm looking for someone to hunt me some wolves!  Are you that person?", giver = 823, ender = 196 }
Q[5623] = { id = 5623, title = "In Favor of the Light", lvl = 4, min = 5, classes = 16, text = "Hello again, young $gpriest:priestess;. The time has come for you to learn more about our religion. After you've completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.", goal = "Speak to Priestess Josetta in Elwynn Forest.", done = "I'm glad you've arrived, $N. We have much to discuss about your future and your path within the Light.", giver = 375, ender = 377, enderName = "Priestess Josetta" }
